  // 11. LAYER 9: ĐÔI MẮT XANH NGỌC LAM CYAN ĐIỆN QUANG TO TRÒN (Giant 3-Point Specular Eyes)
  drawZeraoraEye(ctx, -10.5, -13, 9.5, 13.5, -0.22, blink, false);
  drawZeraoraEye(ctx, 10.5, -13, 9.5, 13.5, 0.22, blink, true);

  // 12. LAYER 10: MŨI, MIỆNG CƯỜI & RĂNG NANH MÈO (Muzzle, Mouth & Cat Fangs)
  // Mũi nhỏ xíu
  ctx.fillStyle = "#13161C";
  ctx.beginPath(); ctx.moveTo(-3, -6); ctx.lineTo(3, -6); ctx.lineTo(0, -3.5); ctx.closePath(); ctx.fill();

  // Miệng cười dũng cảm
  ctx.save();
  ctx.beginPath();
  ctx.moveTo(-7.5, -1.2);
  ctx.lineTo(0, 5.8);
  ctx.lineTo(7.5, -1.2);
  ctx.closePath();
  ctx.fillStyle = "#611C28";
  ctx.fill();
  ctx.strokeStyle = "#401018";
  ctx.lineWidth = 1.0;
  ctx.stroke();

  // Lưỡi hồng đào
  ctx.fillStyle = "#FF6B8B";
  ctx.beginPath(); ctx.arc(0, 4.4, 3.2, 0, Math.PI * 2); ctx.fill();

  // 2 Răng nanh mèo Chibi trắng tinh
  ctx.fillStyle = "#FFFFFF";
  ctx.beginPath(); ctx.moveTo(-6, -1.2); ctx.lineTo(-3.5, -1.2); ctx.lineTo(-4.8, 2.4); ctx.closePath(); ctx.fill();
  ctx.beginPath(); ctx.moveTo(3.5, -1.2); ctx.lineTo(6, -1.2); ctx.lineTo(4.8, 2.4); ctx.closePath(); ctx.fill();
  ctx.restore();

  ctx.restore(); // restore head scale

  // 13. LAYER 11: BỤI TIA LỬA ĐIỆN PLASMA XANH LAM LÁCH TÁCH (Floating Plasma Sparks)
  drawPlasmaSpark(ctx, 88 + tailSwayX + sparkF1, 30 + tailSwayY, 1.1, "#80F5FF");
  drawPlasmaSpark(ctx, -48 + sparkF2, by - 16 + sparkF1, 0.9, "#00D2FF");
  drawPlasmaSpark(ctx, -28 + sparkF1, by - 52 + sparkF3, 1.2, "#80F5FF");
  drawPlasmaSpark(ctx, 24 + sparkF2, by - 68 + sparkF1, 0.9, "#00D2FF");

  ctx.restore();
}

function drawZeraoraEye(ctx, ex, ey, rx, ry, rot, blink, isRight) {
  ctx.save();
  ctx.translate(ex, ey);
  ctx.rotate(rot);

  if (blink) {
    ctx.strokeStyle = "#0F1115";
    ctx.lineWidth = 3.0;
    ctx.lineCap = "round";
    ctx.beginPath();
    ctx.arc(0, 2, rx * 0.85, Math.PI * 0.12, Math.PI * 0.88);
    ctx.stroke();
    // Khóe vểnh mí mắt dũng cảm
    ctx.beginPath();
    ctx.moveTo(isRight ? rx * 0.7 : -rx * 0.7, 3);
    ctx.lineTo(isRight ? rx * 1.25 : -rx * 1.25, -3);
    ctx.stroke();
  } else {
    // 1. Viền ngoài & Hốc mắt sâu với khóe mắt vểnh dũng cảm
    ctx.beginPath();
    ctx.ellipse(0, 0, rx, ry, 0, 0, Math.PI * 2);
    ctx.fillStyle = "#0F1115";
    ctx.fill();

    // Khóe mắt vểnh dũng cảm (Heroic cat winged flick)
    ctx.fillStyle = "#0F1115";
    ctx.beginPath();
    if (!isRight) {
      ctx.moveTo(-rx * 0.6, -ry * 0.3);
      ctx.lineTo(-rx * 1.45, -ry * 0.7);
      ctx.lineTo(-rx * 0.4, -ry * 0.6);
    } else {
      ctx.moveTo(rx * 0.6, -ry * 0.3);
      ctx.lineTo(rx * 1.45, -ry * 0.7);
      ctx.lineTo(rx * 0.4, -ry * 0.6);
    }
    ctx.closePath();
    ctx.fill();

    // 2. Tròng mắt xanh ngọc lam cyan điện quang đa tầng
    const irisGrad = ctx.createLinearGradient(0, -ry, 0, ry);
    irisGrad.addColorStop(0, "#00457A");
    irisGrad.addColorStop(0.3, "#0077C8");
    irisGrad.addColorStop(0.7, "#00B4D8");
    irisGrad.addColorStop(1, "#64DFDF");
    ctx.beginPath();
    ctx.ellipse(0, 0, rx - 1.4, ry - 1.4, 0, 0, Math.PI * 2);
    ctx.fillStyle = irisGrad;
    ctx.fill();

    // Vòm sáng caustic đáy mắt
    ctx.beginPath();
    ctx.ellipse(0, ry * 0.38, rx * 0.68, ry * 0.44, 0, 0, Math.PI);
    ctx.fillStyle = "rgba(128, 245, 255, 0.65)";
    ctx.fill();

    // 3. 3 ĐIỂM BẮT SÁNG PHA LÊ (3-Point Specular Highlights)
    // Điểm 1: Primary Specular (Bầu dục lớn, góc 10h)
    ctx.fillStyle = "#FFFFFF";
    ctx.beginPath();
    ctx.ellipse(!isRight ? rx * 0.22 : rx * 0.18, -ry * 0.36, rx * 0.36, ry * 0.26, -0.2, 0, Math.PI * 2);
    ctx.fill();

    // Điểm 2: Secondary Caustic (Tròn vừa góc 4h)
    ctx.fillStyle = "rgba(225, 250, 255, 0.92)";
    ctx.beginPath();
    ctx.arc(!isRight ? -rx * 0.26 : -rx * 0.22, ry * 0.32, rx * 0.18, 0, Math.PI * 2);
    ctx.fill();

    // Điểm 3: Tertiary Micro Glint (Hạt pha lê lấp lánh mép ngoài)
    ctx.fillStyle = "#FFFFFF";
    ctx.beginPath();
    ctx.arc(!isRight ? rx * 0.36 : -rx * 0.36, ry * 0.05, rx * 0.11, 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.restore();
}

function drawPlasmaSpark(ctx, x, y, scale, color) {
  ctx.save();
  ctx.translate(x, y);
  ctx.scale(scale, scale);
  ctx.fillStyle = color;
  ctx.beginPath();
  ctx.moveTo(0, -7);
  ctx.quadraticCurveTo(0, 0, 7, 0);
  ctx.quadraticCurveTo(0, 0, 0, 7);
  ctx.quadraticCurveTo(0, 0, -7, 0);
  ctx.quadraticCurveTo(0, 0, 0, -7);
  ctx.fill();
  ctx.fillStyle = "#FFFFFF";
  ctx.beginPath();
  ctx.arc(0, 0, 2.0, 0, Math.PI * 2);
  ctx.fill();
  ctx.restore();
}
